/**
 * Extended entity property that handles factions and levels for the player
 */
public class FactionPlayerHandler extends AttachmentSync implements IFactionPlayerHandler, IPlayerEventListener {
    private final static Logger LOGGER = LogManager.getLogger();

    public static FactionPlayerHandler get(Player player) {
        return player.getData(FactionAttachments.FACTION_PLAYER_HANDLER.get());
    }

    public static <T extends IFactionPlayer<T>> Optional<T> getCurrentFactionPlayer(Player player) {
        return Optional.of(get(player).factionPlayer());
    }

    private final Player player;
    private Holder<? extends IPlayableFaction<?>> currentFaction = DefaultFactions.NEUTRAL;
    private int currentLevel = 0;

    public FactionPlayerHandler(Player player) {
        this.player = player;
    }

    @Override
    public Player asEntity() {
        return player;
    }

    @Override
    public boolean canJoin(Holder<? extends IPlayableFaction<?>> faction) {
        PlayerFactionEvent.CanJoinFaction.Behavior behavior = FactionEventFactory.fireCanJoinFactionEvent(this, currentFaction, faction);
        if (behavior == PlayerFactionEvent.CanJoinFaction.Behavior.ONLY_WHEN_NO_FACTION) {
            return IFaction.is(currentFaction, DefaultFactions.NEUTRAL);
        }
        return behavior == PlayerFactionEvent.CanJoinFaction.Behavior.ALLOW;
    }

    @Override
    public boolean canLeaveFaction() {
        return currentFaction.value().getPlayerCapability(player).canLeaveFaction();
    }

    @Override
    public Holder<? extends IPlayableFaction<?>> getFaction() {
        return currentFaction;
    }

    @SuppressWarnings("unchecked")
    @Override
    public <T extends IFactionPlayer<T>> T factionPlayer() {
        return (T) currentFaction.value().getPlayerCapability(player);
    }

    @Override
    public <T extends IFactionPlayer<T>> Optional<T> factionPlayer(Holder<IFaction<T>> faction) {
        if (IFaction.is(currentFaction, faction)) {
            return Optional.of(factionPlayer());
        } else {
            return Optional.empty();
        }
    }

    @SuppressWarnings("unchecked")
    @Override
    public <T extends ISkillPlayer<T>> Optional<T> getCurrentSkillPlayer() {
        if (factionPlayer() instanceof ISkillPlayer<?> skillPlayer) {
            return Optional.of((T)skillPlayer);
        }
        return Optional.empty();
    }

    @Override
    public <T extends ISkillPlayer<T>> Optional<ISkillHandler<T>> getSkillHandler() {
        return this.<T>getCurrentSkillPlayer().map(ISkillPlayer::getSkillHandler);
    }

    @Override
    public <T extends ISkillPlayer<T>> Optional<IActionHandler<T>> getActionHandler() {
        return this.<T>getCurrentSkillPlayer().map(ISkillPlayer::getActionHandler);
    }

    @Override
    public <TInterface> Optional<TInterface> getExtension(Class<TInterface> type) {
        FactionExtensionType<TInterface> extension = currentFaction.value().extension(type);
        return extension == null ? Optional.empty() : Optional.of(extension.get(player));
    }

    @Override
    public int getCurrentLevel() {
        return currentLevel;
    }

    @Override
    public int getCurrentLevel(Holder<? extends IFaction<?>> f) {
        return isInFaction(f) ? currentLevel : 0;
    }

    @Override
    public float getCurrentLevelRelative() {
        return currentLevel / (float) currentFaction.value().getHighestReachableLevel();
    }

    @Override
    public <T extends IFaction<?>> boolean isInFaction(@Nullable Holder<T> f) {
        return IFaction.is(currentFaction, f);
    }

    @Override
    public <T extends IFaction<?>> boolean isInFaction(@Nullable TagKey<T> f) {
        return IFaction.is(currentFaction, f);
    }

    @Override
    public void joinFaction(Holder<? extends IPlayableFaction<?>> faction) {
        if (canJoin(faction)) {
            setFaction(FactionUpdate.builder().faction(faction).level(1).build());
        }
    }

    @Override
    public boolean onEntityAttacked(DamageSource src, float amt) {
        if (FactionConfig.server().factionPvpOnlyBetweenFactions.get() && src.getEntity() instanceof Player) {
            Holder<? extends IPlayableFaction<?>> otherFaction = get((Player) src.getEntity()).getFaction();
            return IFaction.is(this.currentFaction, otherFaction);
        }
        return false;
    }

    @Override
    public void leaveFaction(boolean die) {
        Holder<? extends IFaction<?>> oldFaction = currentFaction;
        setFaction(FactionUpdate.neutral());
        player.sendOverlayMessage(Component.translatable("command.factionapi.base.level.successful", player.getName(), oldFaction.value().getNameSingular(), 0));
        if (die) {
            DamageHandler.hurtModded((ServerLevel) this.player.level(), player, ModDamageSources::leaveFaction, 10000);
        }
    }

    @Override
    public void checkSkillTreeLocks() {
        if (this.player.level() instanceof ServerLevel level) {
            Registry<ISkillTree> registryAccess = this.player.level().registryAccess().lookupOrThrow(FactionRegistries.Keys.SKILL_TREE);
            getSkillHandler().ifPresent(handler -> handler.updateUnlockedSkillTrees(registryAccess.listElements().filter(s -> s.value().unlockPredicate().matches(level, null, this.player)).collect(Collectors.toList())));
        }
    }

    @Override
    public void onRespawn() {
        if (!IFaction.isNeutral(this.currentFaction)) {
            this.player.addEffect(new MobEffectInstance(FactionEffects.RESURRECTION_FATIGUE, 300));
        }
    }

    @Override
    public void onPlayerLoggedIn() {
        this.player.refreshDisplayName();
    }

    @Override
    public boolean setFaction(FactionUpdate param) {
        var oldFaction = this.currentFaction;
        var oldLevel = this.currentLevel;
        var newFaction = param.getFaction(oldFaction);
        boolean changedFaction = !IFaction.is(currentFaction, newFaction);
        int newLevel = oldLevel;

        if (changedFaction && !param.hasLevelChange()) {
            newLevel = 1;
        }
        if (param.hasLevelChange()) {
            newLevel = param.getLevel();
        }

        newLevel = Math.clamp(newLevel, 0, newFaction.value().getHighestReachableLevel());

        if (changedFaction) {
            if (!this.currentFaction.value().getPlayerCapability(player).canLeaveFaction()) {
                LOGGER.info("You cannot leave faction {}, it is prevented by respective mod", currentFaction.getRegisteredName());
                return false;
            }
        }

        if (FactionEventFactory.fireChangeLevelOrFactionEvent(this, oldFaction, oldLevel, newFaction, newLevel)) {
            LOGGER.debug("Faction or Level change event canceled");
            return false;
        }

        final var finalParam = param.copy()
                .level(newLevel)
                .faction(newFaction).build();
        param = finalParam;

        if (changedFaction) {
            oldFaction.value().getExtensions().values().forEach(extension -> extension.cleanup(this.player));
            oldFaction.value().getPlayerCapability(this.player).leaveFaction();
        }

        this.currentFaction = newFaction;
        this.currentLevel = newLevel;

        newFaction.value().getPlayerCapability(this.player).levelChanged(finalParam);
        newFaction.value().getExtensions().values().forEach(extension -> {
            if (extension.get(player) instanceof IFactionExtension fe) {
                fe.setLevel(finalParam);
            }
        });

        this.checkSkillTreeLocks();

        ScoreboardUtil.updateScoreboard(this.player, ScoreboardUtil.FACTION_CRITERIA, this.currentFaction.value().hashCode());

        if (this.player instanceof ServerPlayer) {
            FactionLogger.info(FactionLogger.FACTION, param.toJson());
        }

        if (changedFaction || oldLevel != newLevel) {
            FactionEventFactory.fireFactionLevelChangedEvent(this, oldFaction, oldLevel, currentFaction, currentLevel);
        }

        FactionEventFactory.fireLevelChangedEvent(this, param);

        this.player.refreshDisplayName();
        sync();
        if (this.player instanceof ServerPlayer serverPlayer) {
            FactionAdvancements.TRIGGER_FACTION.get().trigger(serverPlayer, currentFaction, currentLevel);
        }
        return true;
    }


    //<editor-fold desc="Serialization">


    @Override
    public AttachmentType<?> getType() {
        return FactionAttachments.FACTION_PLAYER_HANDLER.get();
    }

    @Override
    protected void registerProperties() {
        super.registerProperties();
        registerProperty(FIdentifier.mod("faction")).simple(ModCodecs.playableFaction()).defaultValue(DefaultFactions.NEUTRAL).provider(() -> this.currentFaction).commonLoader(holder -> this.currentFaction = holder, Comparator.comparing(x -> x.unwrapKey().orElseThrow())).register();
        registerProperty(FIdentifier.mod("level")).simple(0, () -> this.currentLevel, l -> this.currentLevel = l);
    }

    @Override
    protected void onPropertyChanged() {
        this.player.refreshDisplayName();
    }

    //</editor-fold>

    public void openFactionMenu() {
        if (!player.isAlive()) return;
        if (IFaction.isNeutral(getFaction())) return;
        player.openMenu(new SimpleMenuProvider((i, inventory, player) -> new FactionMenu(i, inventory), Component.empty()));
        getTaskManager().ifPresent(ITaskManager::initializeFactionMenu);
    }

    public static class AttachmentOptions extends AttachmentSynchronization.PlayerOptions<FactionPlayerHandler> {

        @Override
        protected FactionPlayerHandler create(Player player) {
            return new FactionPlayerHandler(player);
        }
    }
}

package de.teamlapen.faction.common.util;

import de.teamlapen.faction.api.world.entities.extensions.IEntity;
import de.teamlapen.sync.BaseAttachmentSyncHandler;
import de.teamlapen.sync.api.IAttachmentSync;
import net.minecraft.world.entity.player.Player;
import net.minecraft.world.level.storage.ValueInput;
import net.minecraft.world.level.storage.ValueOutput;
import net.neoforged.neoforge.attachment.IAttachmentHolder;
import net.neoforged.neoforge.attachment.IAttachmentSerializer;
import org.jetbrains.annotations.NotNull;

public abstract class AttachmentSynchronization<T extends IAttachmentSync & IEntity, Z extends IAttachmentHolder> extends BaseAttachmentSyncHandler<@NotNull T> implements IAttachmentSerializer<T> {

    @Override
    public T read(IAttachmentHolder holder, ValueInput input) {
        T attachment = apply(holder);
        attachment.deserialize(input);
        return attachment;
    }

    protected abstract T create(Z player);

    @Override
    public boolean write(T attachment, ValueOutput output) {
        attachment.serialize(output);
        return true;
    }

    public static abstract class PlayerOptions<T extends IAttachmentSync & IEntity> extends AttachmentSynchronization<T, Player> {
        @Override
        public T apply(IAttachmentHolder holder) {
            if (holder instanceof net.minecraft.world.entity.player.Player player) {
                return create(player);
            }
            throw new IllegalArgumentException("Cannot create attachment for holder " + holder.getClass() + ". Expected Player");
        }
    }
}

package de.teamlapen.faction.common.util;

import com.mojang.serialization.Codec;
import com.mojang.serialization.DataResult;
import com.mojang.serialization.Keyable;
import de.teamlapen.faction.api.FactionRegistries;
import de.teamlapen.faction.api.factions.IFaction;
import de.teamlapen.faction.api.factions.IPlayableFaction;
import de.teamlapen.faction.api.factions.actions.IAction;
import de.teamlapen.faction.api.factions.skills.ISkill;
import de.teamlapen.faction.api.factions.skills.ISkillPlayer;
import de.teamlapen.faction.common.core.ModRegistries;
import de.teamlapen.faction.common.factions.actions.ActionKeys;
import net.minecraft.core.*;
import net.minecraft.core.registries.BuiltInRegistries;
import net.minecraft.world.entity.Entity;
import net.minecraft.world.entity.EntityType;
import net.minecraft.world.phys.AABB;
import org.jetbrains.annotations.NotNull;

import java.util.List;
import java.util.Map;

public class ModCodecs {

    public static final Codec<AABB> AABB = Codec.DOUBLE.listOf(6,6).xmap(x -> new AABB(x.get(0),x.get(1),x.get(2),x.get(3),x.get(4),x.get(5)), x -> List.of(x.minX,x.minY,x.minZ,x.maxX,x.maxY,x.maxZ));

    @SuppressWarnings({"RedundantCast", "unchecked"})
    public static Codec<Holder<? extends IPlayableFaction<?>>> playableFaction() {
        return ModRegistries.FACTIONS.holderByNameCodec().xmap(s -> (Holder<? extends IPlayableFaction<?>>) (Object) s, s -> (Holder<IFaction<?>>) (Object) s);
    }

    @SuppressWarnings({"unchecked", "RedundantCast"})
    public static Codec<HolderSet<? extends IPlayableFaction<?>>> playableFactionSet() {
        return RegistryCodecs.homogeneousList(FactionRegistries.Keys.FACTION)
                .flatXmap(x -> DataResult.success((HolderSet<? extends IPlayableFaction<?>>) (Object) x), x -> DataResult.success((HolderSet<IFaction<?>>) (Object)x));
    }

    @SuppressWarnings("unchecked")
    public static Codec<Holder<? extends IFaction<?>>> faction() {
        return (Codec<Holder<? extends IFaction<?>>>) (Object) ModRegistries.FACTIONS.holderByNameCodec();
    }

    @SuppressWarnings("unchecked")
    public static Codec<Holder<? extends IFaction<?>>> faction(RegistryAccess registryAccess) {
        var registry = registryAccess.lookupOrThrow(FactionRegistries.Keys.FACTION);
        return (Codec<Holder<? extends IFaction<?>>>) (Object) registry.holderByNameCodec();
    }

    @SuppressWarnings("unchecked")
    public static Codec<Holder<? extends IAction<?>>> action() {
        return (Codec<Holder<? extends IAction<?>>>) (Object) ModRegistries.ACTIONS.holderByNameCodec();
    }

    @SuppressWarnings("unchecked")
    public static <T extends ISkillPlayer<@NotNull T>> Codec<Holder<ISkill<@NotNull T>>> skills() {
        return ModRegistries.SKILLS.holderByNameCodec().comapFlatMap(skill -> {
            try {
                return DataResult.success((Holder<ISkill<@NotNull T>>) (Object) skill);
            } catch (Exception e) {
                return DataResult.error(() -> "Could not find skill " + skill);
            }
        }, (Holder<ISkill<@NotNull T>> skill) -> (Holder<ISkill<?>>) (Object) skill);
    }

    @SuppressWarnings("unchecked")
    public static <T extends Entity> Codec<EntityType<T>> entityCodec() {
        return BuiltInRegistries.ENTITY_TYPE.byNameCodec().comapFlatMap(entityType -> {
            try {
                return DataResult.success((EntityType<T>) entityType);
            } catch (Exception e) {
                return DataResult.error(() -> "Could not find entity type " + entityType);
            }
        }, (EntityType<T> x) -> x);
    }

}

package de.teamlapen.sync;

import de.teamlapen.sync.api.ISyncable;
import de.teamlapen.sync.properties.IProperty;
import de.teamlapen.sync.properties.Property;
import net.minecraft.resources.Identifier;
import net.minecraft.world.level.storage.ValueInput;
import net.minecraft.world.level.storage.ValueOutput;
import net.neoforged.neoforge.common.util.ValueIOSerializable;
import org.jetbrains.annotations.ApiStatus;
import org.jetbrains.annotations.MustBeInvokedByOverriders;

import java.util.*;

/**
 * Base class for sync-able properties.
 * <p>
 * Handles registering, syncing ob properties
 * <p>
 * To make use of this class, you need to override {@link #registerProperties()}. In the implementation you can register properties.
 * <p>
 * Properties are registered using {@link #registerProperty(Identifier)}.
 * <p>
 * To handle property changes, override {@link #onPropertyChanged()}.
 */
public abstract class PropertySync implements ValueIOSerializable, ISyncable, IProperty {

    private final Map<Identifier, Property> propertiesMap = new HashMap<>();
    protected final Collection<Property> properties = Collections.unmodifiableCollection(propertiesMap.values());

    public PropertySync() {
        this.registerProperties();
    }

    /**
     * This method is called in the constructor of this class.
     * It should be used to register properties using {@link #registerProperty(Identifier)}
     */
    @ApiStatus.OverrideOnly
    protected void registerProperties() {

    }

    //<editor-fold desc="IProperty">

    @Override
    public int getStatus() {
        return Objects.hash(this.properties.stream().map(Property::getStatus).toList());
    }

    @Override
    public boolean hasClientSync() {
        return this.properties.stream().anyMatch(Property::hasClientSync);
    }

    @Override
    public boolean hasServerLoad() {
        return this.properties.stream().anyMatch(Property::hasServerLoad);
    }

    //</editor-fold>

    //<editor-fold desc="Properties">

    @ApiStatus.OverrideOnly
    protected void onPropertyChanged() {

    }

    public final void registerProperty(Property property) {
        this.propertiesMap.put(property.key(), property);
    }

    protected final Property.PropertyBuilder registerProperty(Identifier key) {
        return new Property.PropertyBuilder(this, key);
    }

    //</editor-fold>

    //<editor-fold desc="Serialization">

    @Override
    @MustBeInvokedByOverriders
    public void serialize(ValueOutput output) {
        for (Property syncProperty : this.properties) {
            if (syncProperty.hasServerLoad()) {
                syncProperty.storeValue(output, Property.StoreMode.FULL);
            }
        }
    }

    @Override
    @MustBeInvokedByOverriders
    public void deserialize(ValueInput input) {
        for (Property syncProperty : this.properties) {
            if (!syncProperty.hasServerLoad()) continue;
            syncProperty.loadServer(input);
        }

        onPropertyChanged();
    }

    @Override
    public final void serializeFullUpdate(ValueOutput output) {
        for (Property property : this.properties) {
            if (property.hasClientSync()) {
                property.store(output, Property.StoreMode.FULL_UPDATE);
            }
        }
    }

    @Override
    public final void serializeUpdate(ValueOutput output) {
        for (Property property : this.properties) {
            if (property.hasClientSync() && property.hasChanged()) {
                property.store(output, Property.StoreMode.UPDATE);
            }
        }
    }

    @Override
    public final boolean deserializeUpdate(ValueInput input) {
        boolean changed = false;
        for (Property property : this.properties) {
            if (property.hasClientSync()) {
                changed = property.loadClient(input) || changed;
            }
        }

        if (changed) {
            onPropertyChanged();
            return true;
        }
        return false;
    }

    //</editor-fold>
}

package de.teamlapen.sync.properties;

import com.google.common.base.Preconditions;
import com.mojang.serialization.Codec;
import net.minecraft.resources.Identifier;
import net.minecraft.world.level.storage.ValueInput;
import net.minecraft.world.level.storage.ValueOutput;
import org.jetbrains.annotations.Nullable;

import java.util.Comparator;
import java.util.Optional;
import java.util.function.Consumer;
import java.util.function.Function;
import java.util.function.Supplier;

public class SimpleProperty<T> extends Property {

    private final Codec<T> codec;
    private final Supplier<T> defaultValue;
    private final Supplier<T> valueProvider;
    private final DataApply<T> valueSetter;

    public SimpleProperty(Identifier key, Codec<T> codec, Supplier<T> defaultValue, Supplier<T> valueProvider, DataApply<T> valueSetter) {
        super(key);
        this.codec = codec;
        this.defaultValue = defaultValue;
        this.valueProvider = valueProvider;
        this.valueSetter = valueSetter;
    }

    @Override
    public boolean hasClientSync() {
        return this.valueSetter.canLoadClient();
    }

    @Override
    public boolean hasServerLoad() {
        return this.valueSetter.canLoadServer();
    }

    @Override
    public int getStatus() {
        return this.valueProvider.get().hashCode();
    }

    public int storeValue(ValueOutput output, StoreMode mode) {
        T t = this.valueProvider.get();
        output.store(this.key.toString(), this.codec, t);

        return t.hashCode();
    }

    public boolean loadClient(ValueInput input) {
        if (!this.valueSetter.canLoadClient()) return false;

        return input.read(this.key.toString(), this.codec).map(valueSetter::loadClient).orElse(false);
    }

    public void loadServer(ValueInput input) {
        if (!this.valueSetter.canLoadServer()) return;

        var value = input.read(this.key.toString(), this.codec).orElseGet(this.defaultValue);
        this.valueSetter.loadServer(value);
    }

    public static class Builder<T> {

        private final PropertyBuilder baseBuilder;
        private final Codec<T> codec;
        @Nullable
        private Supplier<T> defaultValue;
        @Nullable
        private Supplier<T> supplier;
        @Nullable
        private Consumer<T> serverLoader;
        @Nullable
        private Function<T, Boolean> clientLoader;
        @Nullable
        private Consumer<T> clientLoaderSimple;
        @Nullable
        private Comparator<T> comparator;

        public Builder(PropertyBuilder baseBuilder, Codec<T> codec) {
            this.baseBuilder = baseBuilder;
            this.codec = codec;
        }

        public Builder<T> defaultValue(T defaultValue) {
            this.defaultValue = () -> defaultValue;
            return this;
        }

        public Builder<T> defaultValue(Supplier<T> defaultValue) {
            this.defaultValue = defaultValue;
            return this;
        }

        public Builder<T> provider(Supplier<T> supplier) {
            this.supplier = supplier;
            return this;
        }

        public Builder<T> serverLoader(Consumer<T> loader) {
            this.serverLoader = loader;
            return this;
        }

        public Builder<T> clientLoader(Function<T, Boolean> loader) {
            this.clientLoader = loader;
            return this;
        }

        public Builder<T> commonLoader(Function<T, Boolean> loader) {
            this.serverLoader = loader::apply;
            this.clientLoader = loader;
            return this;
        }

        public Builder<T> commonLoader(Consumer<T> loader, Comparator<T> comparator) {
            this.serverLoader = loader;
            this.clientLoaderSimple = loader;
            this.comparator = comparator;
            return this;
        }

        public Builder<T> comparator(Comparator<T> comparator) {
            this.comparator = comparator;
            return this;
        }

        public void register() {
            Preconditions.checkArgument( this.defaultValue != null, "Default value must be set");
            Preconditions.checkArgument( this.supplier != null, "Supplier must be set");
            Preconditions.checkArgument( this.serverLoader != null ||  this.clientLoader != null, "Server or client loaders must be set");
            Preconditions.checkArgument(this.clientLoaderSimple == null || this.clientLoader == null, "Only one of clientLoader or clientLoaderSimple can be set");
            Preconditions.checkArgument(this.clientLoader != null || (this.clientLoaderSimple == null || this.comparator != null), "Comparator must be set if clientLoaderSimple is set");

            if (this.clientLoader != null && this.comparator != null) {
                this.clientLoader = value -> {
                    assert this.supplier != null;
                    assert this.clientLoader != null;
                    assert comparator != null;

                    T t = this.supplier.get();
                    this.clientLoader.apply(value);
                    return comparator.compare(t, value) != 0;
                };
            }

            if (this.clientLoaderSimple != null) {
                this.clientLoader = value -> {
                    assert this.supplier != null;
                    assert this.clientLoaderSimple != null;
                    assert comparator != null;

                    T t = this.supplier.get();
                    this.clientLoaderSimple.accept(value);
                    return comparator.compare(t, value) != 0;
                };
            }

            this.baseBuilder.register(key -> {
                assert this.defaultValue != null;
                assert this.supplier != null;
                return new SimpleProperty<>(key, this.codec, this.defaultValue, this.supplier, DataApply.create(serverLoader, clientLoader));
            });
        }


    }

    public static class NullableBuilder<T> {

        private final Builder<Optional<T>> innerBuilder;

        public NullableBuilder(PropertyBuilder baseBuilder, Codec<@Nullable T> codec) {
            this.innerBuilder = new Builder<>(baseBuilder,  Codec.optionalField("value", codec, true).codec()).defaultValue(Optional.empty());
        }

